// fill between the rows of a key table with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;      // outside the range, hold the end value
  for (let i = 0; i + 1 < keys.length; i++) {
    const a = keys[i], b = keys[i + 1];
    if (frame <= b.frame) {
      const t = (frame - a.frame) / (b.frame - a.frame);  // progress inside the segment, 0–1
      return a.value + (b.value - a.value) * a.curve(t);  // advance the gap along the curve
    }
  }
  return keys[keys.length - 1].value;
}

const FPS = 30;          // frames per second of this demo
const LOOP_FRAMES = 90;  // loop length — one breath every 3 seconds
const linear = (t) => t; // for segments between equal values — any curve, no movement

// the breath — separate curves for opening and closing; equal values hold in between
const BREATH = [
  { frame: 0,  value: 0,   curve: cubicBezier(0.7, 0.01, 0.21, 1) },
  { frame: 30, value: 1,   curve: linear },
  { frame: 44, value: 1,   curve: cubicBezier(0.75, 0, 0.3, 1) },
  { frame: 73, value: 0 },
];
// the rotation — same frame ranges as the breath, with 2 curves of its own
const SPIN = [
  { frame: 0,  value: 0,   curve: cubicBezier(0.68, 0.03, 0.24, 1) },
  { frame: 30, value: 0.5, curve: linear },
  { frame: 44, value: 0.5, curve: cubicBezier(0.69, -0.05, 0.34, 1) },
  { frame: 73, value: 1 },
];
// the edge rail — a radius round trip on its own frame ranges
const RAIL = [
  { frame: 10, value: 32.84, curve: cubicBezier(0.5, 0.04, 0.2, 1) },
  { frame: 28, value: 65.68, curve: linear },
  { frame: 44, value: 65.68, curve: cubicBezier(0.81, 0, 0.35, 1) },
  { frame: 70, value: 32.84 },
];

const RADIUS_REST = 28.8;          // hexagon radius — closed
const RADIUS_PEAK = 75.6;          // hexagon radius — fully open
const SPIN_DEGREES = -180;         // rotation per loop
const CENTER = { x: 120, y: 120 }; // center of the drawing canvas
const rad = (deg) => (deg * Math.PI) / 180; // degrees → radians

// frame number in, position and size of all 19 dots out
function latticeAt(frame) {
  const breath = keyAt(BREATH, frame);
  const radius = RADIUS_REST + (RADIUS_PEAK - RADIUS_REST) * breath; // only the radius rides the breath
  const spin = SPIN_DEGREES * keyAt(SPIN, frame);
  return DOTS.map((dot) => ({
    angle: dot.angle + spin,                       // every dot rides the same rotation
    dist: dot.role === "arm"  ? radius             // base dots — the breath's radius
        : dot.role === "edge" ? keyAt(RAIL, frame) // edge dots — the dedicated rail
        : dot.dist,                                // center and inner ring — the row's distance (0 and 38.1)
    scale: dot.grow ? keyAt(dot.grow, frame) : 1,  // appearing and leaving are scale keys
  }));
}

// from angle and distance to screen coordinates
function dotXY(dot) {
  return {
    x: CENTER.x + dot.dist * Math.cos(rad(dot.angle)),
    y: CENTER.y - dot.dist * Math.sin(rad(dot.angle)), // the screen's y axis points down, hence −sin
  };
}

