const linear = (t) => t; // for segments between equal values — the hold costs nothing

const FPS = 30;         // playback rate — LOOP_FRAMES / FPS = 3 seconds
const LOOP_FRAMES = 90; // frames in 1 loop
const CLIP_START = 3;   // frame where the first duplicate starts
const STEP_FRAMES = 2;  // start offset between duplicates, in frames

const R_REST = 12.02;  // rest radius
const R_PEAK = 26.19;  // pop peak
const R_UNDER = 21.84; // the key placed deliberately low
const R_HOLD = 22.39;  // the recover-and-hold radius

const CLIP = [ // value = radius. Each row's curve belongs to the segment toward the next key
  { frame: 0,  value: R_REST,  curve: cubicBezier(0.62, 0.08, 0.5, 0.92) }, // → pop
  { frame: 9,  value: R_PEAK,  curve: cubicBezier(0.32, 0.06, 0.5, 1.0) },  // → drop too far
  { frame: 18, value: R_UNDER, curve: cubicBezier(0.48, 0.38, 0.5, 0.88) }, // → recover
  { frame: 25, value: R_HOLD,  curve: linear },                             // → hold for 25 frames
  { frame: 50, value: R_HOLD,  curve: cubicBezier(0.2, 0.17, 0.2, 0.83) },  // → back to rest
  { frame: 68, value: R_REST },
];
const ORDER = [[5, 1, 6], [7, 3, 4], [8, 2, 0]]; // the entire "random" is this table

// frame number in, 9 radii out
function radiiAt(frame) {
  return ORDER.flat().map((rank) => {
    const local = frame - CLIP_START - rank * STEP_FRAMES; // each replay starts later by its rank
    return keyAt(CLIP, local);                             // fill between keys with the segment curves
  });
}

// fill between the rows of a key table with curves — every motion in this article has this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;      // outside the range, hold the end value
  for (let i = 0; i + 1 < keys.length; i++) {
    const a = keys[i], b = keys[i + 1];
    if (frame <= b.frame) {
      const t = (frame - a.frame) / (b.frame - a.frame);  // progress inside the segment, 0–1
      return a.value + (b.value - a.value) * a.curve(t);  // advance the gap along the curve
    }
  }
  return keys[keys.length - 1].value;
}

const SIDE = 54;        // square side (px) — same for all three
const GAP = 0.1;        // clearance that keeps the sides just clear (px)
const DIAMOND_DEG = 45; // the diamond angle (degrees)
const QUARTER_DEG = 90; // the law repeats after this much rotation (degrees) — every quarter turn
const FPS = 30;         // playback rate (frames per second)
const LOOP_FRAMES = 90; // length of one loop (frames)

const THETA = [ // value = the center's angle. 3 keys + 2 segment curves — nothing else is keyed
  { frame: 3,  value: 0,           curve: cubicBezier(0.67, 0.06, 0.16, 1.0) },  // → climb to the diamond
  { frame: 46, value: DIAMOND_DEG, curve: cubicBezier(0.76, 0.04, 0.19, 0.98) }, // → descend to upright
  { frame: 89, value: QUARTER_DEG },
];

// frame number in, center angle and side positions out
function squaresAt(frame) {
  const angle = keyAt(THETA, frame);
  // the one-line law: a rotated square's half-width depends on the distance from the diamond
  const phi = Math.abs(((angle % QUARTER_DEG) + QUARTER_DEG) % QUARTER_DEG - DIAMOND_DEG);
  const halfWidth = (SIDE / Math.SQRT2) * Math.cos((phi * Math.PI) / 180);
  const push = Math.max(0, halfWidth - SIDE / 2 - GAP); // push while keeping the GAP clearance
  return {
    center: { rotate: angle },
    left:   { x: 66 - push },  // zero keys on the sides — the law is symmetric
    right:  { x: 174 + push },
  };
}

// fill between the rows of a key table with curves — every motion in this article has this shape
