const FPS = 30;          // frames per second
const LOOP_FRAMES = 90;  // length of one full loop, in frames
const MID_FRAME = 45;    // the frame where the turnaround key sits
const R_REST = 54;       // radius at both end keys (px)
const R_MID = 27;        // radius at the turnaround key (px)
const R_SUM = 81;        // the 2 radii add up to this on every frame
const CONTACT = 120;     // the fixed contact point (same value for x and y)

const R1 = [ // value = the top-left radius. 3 keys + 2 segment curves — nothing else is keyed
  { frame: 0,           value: R_REST, curve: cubicBezier(0.777, 0.029, 0.173, 1.016) }, // → shrink
  { frame: MID_FRAME,   value: R_MID,  curve: cubicBezier(0.765, 0.02, 0.155, 1.024) },  // → grow; the rendered valley lands near frame 44.1 via the overshoot
  { frame: LOOP_FRAMES, value: R_REST },
];

// frame number in, both centres and radii out
function circlesAt(frame) {
  const r1 = keyAt(R1, frame);              // the top-left radius
  const r2 = R_SUM - r1;                    // bottom-right: zero keys — one subtraction
  const d = Math.SQRT1_2;                   // the 45° diagonal component (= cos 45°)
  return [
    { r: r1, x: CONTACT - r1 * d, y: CONTACT - r1 * d }, // recede up-left from the contact
    { r: r2, x: CONTACT + r2 * d, y: CONTACT + r2 * d }, // recede down-right from the contact
  ];
}

// Only one thing moves: a single rotation. Everything else re-reads it.
const FPS = 30;            // playback rate, frames per second
const LOOP_FRAMES = 90;    // length of the whole loop, in frames
const SWEEP_FRAMES = 79;   // last rotation key — rest from here to the loop end
const COPIES = 9;          // number of trailing copies
const DELAY_FRAMES = 1.65; // lag per copy, in frames
const DECAY = 0.77;        // opacity ratio per copy
const CENTER = 120;        // orbit center (same value for x and y)
const ORBIT_RADIUS = 72.5; // orbit radius
const DOT_RADIUS = 16.5;   // dot radius
const REST_ANGLES = [-90, 90]; // rest angles of the 2 dots on opposite sides
const rad = (deg) => (deg / 360) * 2 * Math.PI; // degrees to radians

const ease = cubicBezier(0.82, 0.003, 0.163, 0.996); // the face of the motion — your knob

// frame number in, list of circles out (loops every LOOP_FRAMES frames)
function dotsAt(frame) {
  const dots = [];
  for (const rest of REST_ANGLES) {
    for (let copy = 0; copy <= COPIES; copy++) {     // 0 = lead, then the copies
      const past = frame - copy * DELAY_FRAMES;      // each copy reads slightly into the past
      const t = Math.min(Math.max(past / SWEEP_FRAMES, 0), 1); // progress, clamped to 0–1
      dots.push({
        angle: rest + 360 * ease(t),                 // one full lap
        opacity: DECAY ** copy,                      // DECAY× thinner per copy
      });
    }
  }
  return dots;
}

// Only one thing moves: a single pulse. Every shape just reads it through its own motion amounts.
const FPS = 30;          // frames per second of this demo
const LOOP_FRAMES = 90;  // loop length — one round trip in 3 seconds
const VIEWBOX = 240;     // the canvas is a VIEWBOX × VIEWBOX square
const BAR_CAP = 13.75;     // the bars' corner radius rx — half the width makes the round cap
const SQUARE_CORNER = 2.5; // the center square's corner radius rx

const ease = cubicBezier(0.684, 0.036, 0.292, 0.985); // the face of the motion — your knob

// the pulse's key table: 0 → 1 → (stays 1) → 0, gaps filled by ease
const pulseKeys = [
  { frame: 2,  value: 0, curve: ease },
  { frame: 42, value: 1, curve: ease }, // 42–47 stays at 1 = the held pause
  { frame: 47, value: 1, curve: ease }, // the way back — values run 1 → 0, so the same curve simply runs downhill
  { frame: 87, value: 0, curve: ease },
];

// fill the gaps between key rows with a curve — every move in this article fits this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;      // outside the range, hold the edge value
  for (let i = 0; i + 1 < keys.length; i++) {
    const a = keys[i], b = keys[i + 1];
    if (frame <= b.frame) {
      const t = (frame - a.frame) / (b.frame - a.frame);  // progress through the span, 0–1
      return a.value + (b.value - a.value) * a.curve(t);  // advance the difference along the curve
    }
  }
  return keys[keys.length - 1].value;
}

// per-shape motion-amount table: where it sits, and how far one pulse moves it
const shapes = [
  { x: 51,  w: 27.5, h: 51.5, growW: 0,  growH: 123, slide: -19.85, spin: 0   },
  { x: 85,  w: 27.5, h: 51.5, growW: 0,  growH: 36,  slide: -12.7,  spin: 0   },
  { x: 120, w: 21.5, h: 19.5, growW: 12, growH: 12,  slide: 0,      spin: 180 },
  { x: 155, w: 27.5, h: 51.5, growW: 0,  growH: 36,  slide: 12.7,   spin: 0   },
  { x: 189, w: 27.5, h: 51.5, growW: 0,  growH: 123, slide: 19.85,  spin: 0   },
];

// frame number in, placements out (loops every LOOP_FRAMES)
function shapesAt(frame) {
  const pulse = keyAt(pulseKeys, frame % LOOP_FRAMES);
  return shapes.map((s) => ({
    cx: s.x + s.slide * pulse,            // horizontal position — left gets minus, right gets plus
    cy: VIEWBOX / 2,                      // vertical stays fixed — mid-canvas height
    width:  s.w + s.growW * pulse,
    height: s.h + s.growH * pulse,
    angle:  s.spin * pulse,               // only the center turns, 0–180°
  }));
}

// Only one thing moves: the head's progress u. 0 is the track start; 1 is a full lap.
const FPS = 30;                // frames per second — 90 frames make the 3s loop
const PERIOD_FRAMES = 90;      // frames in one lap = the loop length
const WHIP_START_FRAME = 3;    // loop-local frame where the whip starts
const WHIP_DUR_FRAMES = 51;    // length of the whip beat, in frames
const U_AT_WHIP_START = 0.357; // u at the moment the whip starts = the launch spot
const WHIP_SPAN = 0.901;       // share of the lap the whip eats

// The crawl is the leftover — not yours to choose
const CRAWL_SPAN = 1 - WHIP_SPAN;                         // share left for the crawl = 0.099
const CRAWL_DUR_FRAMES = PERIOD_FRAMES - WHIP_DUR_FRAMES; // frames left for the crawl = 39

// On-screen numbers — the stroke window and the dot
const VIEWBOX = 324;          // canvas side length (px)
const STROKE_WIDTH = 15.6;    // width of the thick stroke (px)
const DOT_RADIUS = 13.5;      // radius of the head dot (px)
const DRAWN_FRACTION = 0.896; // drawn share of the track, full length taken as 1
const GAP_FRACTION = 1 - DRAWN_FRACTION; // the undrawn gap
const PAINT_HEAD_LAG = 0.054; // measured nudge that keeps the gap straddling the dot

const whip = cubicBezier(0.85, 0.191, 0.349, 0.833); // the whip's face — this is the dial
const linear = (t) => t;                              // the crawl just moves straight

// u's key table: the whip eats WHIP_SPAN of the lap; the rest is the straight line home
const uKeys = [
  { frame: 0,               value: U_AT_WHIP_START,             curve: whip   }, // whip start = launch spot
  { frame: WHIP_DUR_FRAMES, value: U_AT_WHIP_START + WHIP_SPAN, curve: linear }, // whip end
  { frame: PERIOD_FRAMES,   value: U_AT_WHIP_START + 1 },                        // same spot, one lap later — not yours to choose
];

// fill between the keys with the curve — every motion in this article fits this shape
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;      // outside the range, hold the edge value
  for (let i = 0; i + 1 < keys.length; i++) {
    const a = keys[i], b = keys[i + 1];
    if (frame <= b.frame) {
      const t = (frame - a.frame) / (b.frame - a.frame);  // progress through the span, 0 to 1
      return a.value + (b.value - a.value) * a.curve(t);  // advance the difference in the curve's shape
    }
  }
  return keys[keys.length - 1].value;
}

// frame number → head progress. Align the whip's start to 0, then read the table
function uAt(frame) {
  const local = ((frame - WHIP_START_FRAME) % PERIOD_FRAMES + PERIOD_FRAMES) % PERIOD_FRAMES;
  return keyAt(uKeys, local) % 1; // anything past 1 wraps into the next lap
}
